"""Build the twelve standalone family recipes and their mobile-first directory."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'SUPER.ASHDOD/recipes';data=json.loads((D/'recipes.json').read_text());recipes=data['recipes'];esc=lambda s:html.escape(str(s),quote=True)
def money(n):return f'{n:.1f}'.rstrip('0').rstrip('.')
def cost_range(r):return f"{money(r['total']/5)}–{money(r['total']/4)}"
def head(title,depth=0):
 prefix='../' if depth else ''
 return f'''<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#173d35"><meta name="description" content="12 ארוחות משפחתיות מלאות ל־4–5 סועדים, עם תמונות, הוראות הכנה ואומדן עלות של 8–15 שקלים לסועד."><title>{esc(title)} | מחירי הסופר בעיר</title><link rel="stylesheet" href="{prefix}recipes.css"><script defer src="{prefix}recipes.js"></script></head>'''
def header(depth=0):
 market='../../' if depth else '../';listing='../' if depth else '#recipes'
 return f'''<header class="site-head"><div class="wrap head-inner"><a class="brand" href="{market}"><span class="isnet">ISNET</span><span>מחירי הסופר בעיר<small>מבשלים בבית · קונים חכם</small></span></a><nav class="head-links" aria-label="ניווט ראשי"><a href="{listing}">כל המתכונים</a><a href="{market}">לאתר הסופרים ←</a></nav></div></header>'''
def footer(depth=0):
 market='../../' if depth else '../';method='../#pricing' if depth else '#pricing'
 return f'''<footer class="footer"><div class="wrap"><p>מחירי הסופר בעיר · רשת ISNET · <a href="{market}">לאתר הסופרים</a> · <a href="{method}">איך חושב המחיר?</a></p><p>כל התמונות נוצרו באמצעות AI להמחשת המנות. המתכונים והעלויות הם הצעות לתכנון ביתי; התאימו את גודל המנה לצורכי הסועדים.</p><p>רשימות המצרכים שסימנתם נשמרות בדפדפן הזה בלבד. אין הזמנה או רכישה.</p></div></footer>'''
def card(r,depth=0):
 url=r['slug']+'/' if not depth else '../'+r['slug']+'/'
 image='images/'+r['slug']+'.webp' if not depth else '../images/'+r['slug']+'.webp'
 search=' '.join([r['title'],r['subtitle'],r['category']]+[x['name'] for x in r['ingredients']]).lower()
 return f'''<article class="recipe-card" data-recipe-card data-category="{esc(r['category'])}" data-search="{esc(search)}"><a class="card-picture" href="{url}" aria-label="למתכון {esc(r['title'])}"><img src="{image}" alt="המחשה של {esc(r['title'])} — {esc(r['subtitle'])}" loading="lazy" width="768" height="576"><span class="category">{esc(r['category'])}</span></a><div class="card-body"><h3><a href="{url}">{esc(r['title'])}</a></h3><p>{esc(r['subtitle'])}</p><div class="card-meta">{r['minutes']} דקות בסך הכול · ל־4–5 סועדים</div><div class="card-bottom"><div class="cost"><strong>₪{cost_range(r)}</strong><span>לסועד · אומדן לכמויות במתכון</span></div><a class="read-link" href="{url}">למתכון המלא ←</a></div></div></article>'''
method='''<details class="method" id="pricing"><summary>איך הגענו ל־<bdi dir="ltr">8–15 ₪</bdi> לסועד?</summary><p>זהו <b>אומדן עלות לחומרי הגלם שנצרכים במתכון</b>, שנערך ב־21.10.2026. הוא כולל גם חלק יחסי של שמן, שום ותבלינים. הטווח לכל סועד הוא עלות אותה ארוחה בחלוקה לחמישה או לארבעה סועדים; הכמויות במתכון נשארות זהות.</p><p>לכל מרכיב מוצגת עלות משוערת עבור הכמות שבמתכון. לדוגמה, 200 גרם משקית עדשים אינם מחיר השקית כולה. קנייה של אריזות שלמות תעלה יותר ותשאיר מצרכים לארוחות הבאות. עלויות חשמל, גז, משלוח ונסיעה אינן כלולות.</p><p>מחירי הייחוס לצורך התכנון כוללים, לדוגמה, חזה עוף בכ־39.90 ₪ לק״ג, שוקיים בכ־31.90 ₪ לק״ג, דג לבן קפוא בכ־40 ₪ לק״ג נטו ואורז בכ־10 ₪ לק״ג. המחירים בפועל תלויים במותג, בכשרות, בעונה ובסניף. אלה הנחות תכנון, ולא הצעת מחיר חיה לסל בסופר מסוים.</p><p>המתכונים עדיין אינם מחוברים אוטומטית למחירי הברקודים באתר. <b>טרם נבדק שכל המרכיבים זמינים יחד בסניף אחד במחיר הזה.</b> כשנחבר מוצרים מדויקים, נוכל להציג גם השוואת סלי קנייה.</p></details>'''
index=head('ארוחה משפחתית ב־8–15 ₪ לסועד')+'<body>'+header()+'''<main class="wrap"><div class="breadcrumbs"><a href="../">מחירי הסופר בעיר</a><span>›</span><span>ארוחות משפחתיות</span></div><section class="hero"><div><span class="eyebrow">משהו טוב מתבשל בבית</span><h1>ארוחה שלמה.<br><em>מחיר שעושה חשק.</em></h1><p class="intro">12 רעיונות לארוחה משפחתית מלאה ב־<strong><bdi dir="ltr">8–15 ₪</bdi> לסועד</strong>. אוכל ביתי עם ירקות, דגנים, קטניות וטעם של עוד.</p><div class="hero-meta"><span>ל־4–5 סועדים</span><span>מצרכים פשוטים</span><span>עלויות גלויות</span></div><a class="btn" href="#recipes">מה מבשלים היום? ←</a></div><div class="hero-photo"><img src="images/chicken-lentil-meatballs.webp" alt="המחשת ארוחה משפחתית: קציצות עוף ועדשים, אורז וסלט כרוב" width="768" height="576" fetchpriority="high"><div class="photo-note"><b>₪8–15</b><span>לסועד · אומדן לחומרי הגלם</span></div></div></section><p class="price-note">המחיר כולל את הכמויות שמשתמשים בהן, גם שמן ותבלינים. אריזות שלמות יעלו יותר. <a href="#pricing">איך חישבנו?</a></p><section id="recipes" aria-label="בחירת מתכון"><div class="filter-panel"><div class="filter-row"><label class="search-box"><span aria-hidden="true">⌕</span><input id="recipeSearch" type="search" placeholder="מה מתחשק? עוף, עדשים, תבשיל…" aria-label="חיפוש לפי מנה או מרכיב"></label><div class="filters" aria-label="סוג הארוחה">'''+''.join(f'<button class="filter" data-category-filter="{c}" aria-pressed="{str(c=="הכול").lower()}">{c}</button>' for c in ['הכול','עוף','טבעוני','צמחוני','דגים','חלבי'])+'''</div></div></div><div class="results-top"><h2>הארוחה הבאה שלכם</h2><span id="resultCount" aria-live="polite">12 ארוחות לבחירה</span></div><div class="recipe-grid">'''+''.join(card(r) for r in recipes)+'''<div class="empty" id="noResults" hidden><h3>לא מצאנו ארוחה בחיפוש הזה</h3><p>נסו מרכיב אחר או חזרו לכל המתכונים.</p><button class="btn secondary" id="clearSearch">לכל הארוחות</button></div></div></section>'''+method+'</main>'+footer()+'</body></html>'
(D/'index.html').write_text(index)
for i,r in enumerate(recipes):
 folder=D/r['slug'];folder.mkdir(exist_ok=True)
 ingredients=''.join(f'''<label class="ingredient"><input type="checkbox" value="{n}" data-label="{esc(x['name']+' — '+x['amount'])}"><span><b>{esc(x['name'])}</b><small>{esc(x['amount'])}</small></span><span class="line-cost">כ־₪{money(x['cost'])}</span></label>''' for n,x in enumerate(r['ingredients']))
 steps=''.join(f'<div class="step"><span class="step-num">{n}</span><p>{esc(step)}</p></div>' for n,step in enumerate(r['steps'],1))
 safety=(f'<p class="food-note">{esc(r["safety"])} <a href="https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart" target="_blank" rel="noopener">מקור לטמפרטורות הבישול: USDA ↗</a></p>' if r['safety'] else '')
 allergens=' · '.join(r['allergens']) if r['allergens'] else 'בדקו את תוויות המוצרים שבחרתם'
 related=[recipes[(i+1)%12],recipes[(i+4)%12],recipes[(i+7)%12]]
 page=head(r['title'],1)+f'''<body class="detail-page" data-recipe="{r['slug']}">'''+header(1)+f'''<main class="wrap"><div class="breadcrumbs"><a href="../../">מחירי הסופר בעיר</a><span>›</span><a href="../">ארוחות משפחתיות</a><span>›</span><span>{esc(r['title'])}</span></div><section class="hero detail-hero"><div><span class="eyebrow">{esc(r['category'])} · ארוחה מלאה לבית</span><h1>{esc(r['title'])}</h1><p class="intro">{esc(r['subtitle'])}</p><div class="detail-meta"><span>{r['minutes']} דקות בסך הכול</span><span>ל־4–5 סועדים</span></div><div class="cost-box"><strong>כ־₪{round(r['total'])} לכל הארוחה</strong><p>5 סועדים: כ־₪{money(r['total']/5)} לאדם · 4 סועדים: כ־₪{money(r['total']/4)} לאדם</p><small>אומדן לעלות הכמויות במתכון, כולל שמן ותבלינים. <a href="../#pricing"><u>איך חושב המחיר?</u></a></small></div><div class="actions"><a class="btn" href="#ingredients">למצרכים ולהכנה ↓</a><button class="btn secondary" id="printRecipe">הדפסת המתכון</button><button class="btn secondary" id="shareRecipe">שיתוף</button></div><p class="status" data-status role="status"></p></div><div class="hero-photo"><img src="../images/{r['slug']}.webp" alt="המחשה של {esc(r['title'])}, {esc(r['subtitle'])}" width="768" height="576" fetchpriority="high"></div></section><div class="recipe-layout"><aside class="ingredients" id="ingredients"><h2>מה צריך לבית?</h2><p class="help">ל־4–5 סועדים. סמנו מה כבר יש בבית והעתיקו רק את מה שחסר. העלות לצד כל מרכיב היא אומדן לכמות שמשתמשים בה.</p>{ingredients}<div class="ingredients-bottom"><p id="pantryCount" class="help" aria-live="polite"></p><button class="btn" data-copy-list>העתקת רשימת ההשלמות</button><button class="clear" id="resetPantry">איפוס הסימונים</button><p class="tiny">הסימונים נשמרים רק בדפדפן הזה. מחיר הארוחה מחושב מכל מרכיביה, גם אם חלקם כבר בבית.</p><p class="status" data-status role="status"></p></div></aside><section class="steps"><h2>ככה מכינים</h2>{steps}<div class="tips"><h3>איפה נחסך הכסף?</h3><p>{esc(r['saving'])}</p></div><div class="plate"><h3>מה יש בצלחת?</h3><p>{esc(r['plate'])}</p></div><p class="food-note"><b>אלרגנים מרכזיים במתכון:</b> {esc(allergens)}. יש לבדוק גם את תוויות המוצרים, התחליפים והתבלינים.</p>{safety}<p class="food-note">במתכונים עם חומוס ושעועית משתמשים בקטניות שכבר בושלו, לא בקטניות יבשות ללא בישול. זמני ההכנה אינם כוללים הפשרה או בישול מוקדם שלהן.</p></section></div><section class="related"><h2>עוד משהו טעים לשבוע הזה</h2><div class="recipe-grid">{''.join(card(x,1) for x in related)}</div></section></main>'''+footer(1)+'''<div class="mobile-actions"><a class="btn secondary" href="../">כל הארוחות</a><button class="btn" data-copy-list>רשימת מצרכים להעתקה</button></div></body></html>'''
 (folder/'index.html').write_text(page)
print('Built 12 recipe pages and directory')
